public class GraphView extends JFrame {
	private static final Color LIGHT_GRAY = new Color(0, 0, 0, 40);

	private static JFrame frame;
	private static GraphPanel graph;
	private static JLabel stepLabel;
	private static JLabel countLabel;


	private Set<Class<?>> classes;

	private Map<Class<?>, Color> colors;

	private FieldStats stats;


	public GraphView(int width, int height, int startMax) {
		stats = new FieldStats();
		classes = new HashSet<>();
		colors = new HashMap<>();

		if (frame == null) {
			frame = makeFrame(width, height, startMax);
		} else {
			graph.newRun();
		}

	}


	public void setColor(Class<?> animalClass, Color color) {
		colors.put(animalClass, color);
		classes = colors.keySet();
	}


	public void showStatus(int step, Field field) {
		graph.update(step, field, stats);
	}


	public boolean isViable(Field field) {
		return stats.isViable(field);
	}


	public void reset() {
		stats.reset();
		graph.newRun();
	}


	private JFrame makeFrame(int width, int height, int startMax) {
		JFrame frame = new JFrame("Graph View");
		frame.setDefaultCloseOperation(JFrame.HIDE_ON_CLOSE);

		Container contentPane = frame.getContentPane();

		graph = new GraphPanel(width, height, startMax);
		contentPane.add(graph, BorderLayout.CENTER);

		JPanel bottom = new JPanel();
		bottom.add(new JLabel("Step:"));
		stepLabel = new JLabel("");
		bottom.add(stepLabel);
		countLabel = new JLabel(" ");
		bottom.add(countLabel);
		contentPane.add(bottom, BorderLayout.SOUTH);

		frame.pack();
		frame.setLocation(20, 600);

		frame.setVisible(true);

		return frame;
	}


	class GraphPanel extends JComponent {
		private static final double SCALE_FACTOR = 0.8;


		private BufferedImage graphImage;
		private int[] lastVal;
		private int yMax;


		public GraphPanel(int width, int height, int startMax) {
			graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			clearImage();
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			yMax = startMax;
		}


		public void newRun() {
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			Graphics g = graphImage.getGraphics();
			g.copyArea(4, 0, width - 4, height, -4, 0);
			g.setColor(Color.BLACK);
			g.drawLine(width - 4, 0, width - 4, height);
			g.drawLine(width - 2, 0, width - 2, height);
			lastVal = new int[classes.size()];
			Arrays.fill(lastVal, height);
			repaint();
		}


		public void update(int step, Field field, FieldStats stats) {

			Graphics g = graphImage.getGraphics();

			int height = graphImage.getHeight();
			int width = graphImage.getWidth();


			g.copyArea(1, 0, width - 1, height, -1, 0);

			stats.reset();

			int i = 0;
			for (Iterator<Class<?>> it = classes.iterator(); it.hasNext(); i++) {
				Class<?> nextClass = it.next();
				int count = stats.getPopulationCount(field, nextClass);


				int y = height - ((height * count) / yMax) - 1;
				while (y < 0) {
					scaleDown();
					y = height - ((height * count) / yMax) - 1;
				}
				g.setColor(LIGHT_GRAY);
				g.drawLine(width - 2, y, width - 2, height);
				g.setColor(colors.get(nextClass));
				g.drawLine(width - 3, lastVal[i], width - 2, y);
				lastVal[i] = y;
			}

			repaint();

			stepLabel.setText("" + step);
			countLabel.setText(stats.getPopulationDetails(field));

		}


		public void scaleDown() {
			Graphics g = graphImage.getGraphics();
			int height = graphImage.getHeight();
			int width = graphImage.getWidth();

			BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
					BufferedImage.TYPE_INT_RGB);
			Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();

			gtmp.scale(1.0, SCALE_FACTOR);
			gtmp.drawImage(graphImage, 0, 0, null);

			int oldTop = (int) (height * (1.0 - SCALE_FACTOR));

			g.setColor(Color.WHITE);
			g.fillRect(0, 0, width, oldTop);
			g.drawImage(tmpImage, 0, oldTop, null);

			yMax = (int) (yMax / SCALE_FACTOR);

			for (int i = 0; i < lastVal.length; i++) {
				lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
			}

			repaint();
		}


		final public void clearImage() {
			Graphics g = graphImage.getGraphics();
			g.setColor(Color.WHITE);
			g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
			repaint();
		}


		public Dimension getPreferredSize() {
			return new Dimension(graphImage.getWidth(), graphImage.getHeight());
		}


		public boolean isOpaque() {
			return true;
		}


		public void paintComponent(Graphics g) {
			if (graphImage != null) {
				g.drawImage(graphImage, 0, 0, null);
			}
		}
	}
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Random;


public class Simulator {


	private static final int DEFAULT_WIDTH = 320;

	private static final int DEFAULT_DEPTH = 200;

	private static final double FLOWER_CREATION_PROBABILITY = 0.07;

	private static final double MOUSE_CREATION_PROBABILITY = 0.07;

	private static final double DUCK_CREATION_PROBABILITY = 0.07;

	private static final double BIRD_CREATION_PROBABILITY = 0.07;

	private static final double WOLF_CREATION_PROBABILITY = 0.03;

	private static final double BEAR_CREATION_PROBABILITY = 0.03;

	private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;

	private static final Weather DEFAULT_WEATHER = Weather.SUN;

	private static final int TIMECYCLE_LENGTH = 4;


	private List<Animal> animals;

	private List<Plant> plants;

	private Field field;

	private int step;

	private SimulatorView gridView;

	private GraphView graphView;

	private TimeCycle currentTimeCycle;

	private Climate climate;

	private int sickPercentage;


	public Simulator() {
		this(DEFAULT_DEPTH, DEFAULT_WIDTH);
		currentTimeCycle = DEFAULT_TIMECYCLE;
	}


	public Simulator(int depth, int width) {
		if (width <= 0 || depth <= 0) {
			System.out.println("The dimensions must be greater than zero.");
			System.out.println("Using default values.");
			depth = DEFAULT_DEPTH;
			width = DEFAULT_WIDTH;
		}


		animals = new ArrayList<>();

		plants = new ArrayList<>();
		field = new Field(depth, width);
		climate = new Climate(DEFAULT_WEATHER);


		gridView = new SimulatorView(depth, width);


		graphView = new GraphView(1000, 500, 500);


		reset();
	}


	public void runLongSimulation() {
		simulate(4000);
	}


	public void simulate(int numSteps) {
		for (int step = 1; step <= numSteps && gridView.isViable(field); step++) {
			simulateOneStep();
			delay(60);
		}
	}


	public void simulateOneStep() {
		step++;
		climate.updateClimate(step);


		for (Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
			Plant plant = it.next();
			plant.increaseStage(climate);
		}


		List<Animal> newAnimals = new ArrayList<>();

		for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
			Animal animal = it.next();
			animal.act(newAnimals, currentTimeCycle);
			if (!animal.isAlive()) {
				it.remove();
			}
		}


		animals.addAll(newAnimals);


		if (step % TIMECYCLE_LENGTH == 0) {
			currentTimeCycle = currentTimeCycle.toggleTimeCycle(currentTimeCycle);
		}


		int count = 0;
		for (Animal i : animals) {
			if (i.isSick()) {
				count++;
			}
		}

		sickPercentage = (count * 100) / animals.size();
		gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
		graphView.showStatus(step, field);
	}


	public void reset() {
		step = 0;
		animals.clear();
		populate();
		currentTimeCycle = TimeCycle.DAY;
		climate.setCurrentWeather(Weather.SUN);

		sickPercentage = 0;
		graphView.reset();
		gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
		graphView.showStatus(step, field);
	}


	private void populate() {
		Random rand = Randomizer.getRandom();
		field.clear();

		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Location location = new Location(row, col);


				if (rand.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
					Flower flower = new Flower(field, location);
					plants.add(flower);
				} else {
					Grass grass = new Grass(field, location);
					plants.add(grass);
				}


				if (rand.nextDouble() <= BIRD_CREATION_PROBABILITY) {
					Bird bird = new Bird(true, field, location);
					animals.add(bird);
					graphView.setColor(Bird.class, bird.getObjectColor(climate));
				} else if (rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
					Mouse mouse = new Mouse(true, field, location);
					animals.add(mouse);
					graphView.setColor(Mouse.class, mouse.getObjectColor(climate));
				} else if (rand.nextDouble() <= DUCK_CREATION_PROBABILITY) {
					Duck duck = new Duck(true, field, location);
					animals.add(duck);
					graphView.setColor(Duck.class, duck.getObjectColor(climate));
				} else if (rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
					Wolf wolf = new Wolf(true, field, location);
					animals.add(wolf);
					graphView.setColor(Wolf.class, wolf.getObjectColor(climate));
				} else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
					Bear bear = new Bear(true, field, location);
					animals.add(bear);
					graphView.setColor(Bear.class, bear.getObjectColor(climate));
				}

			}
		}
	}


	private void delay(int millisec) {
		try {
			Thread.sleep(millisec);
		} catch (InterruptedException ie) {

		}
	}
}

import java.util.HashMap;


public class FieldStats {

	private HashMap<Class, Counter> counters;

	private boolean countsValid;


	public FieldStats() {


		counters = new HashMap<>();
		countsValid = true;
	}


	public String getPopulationDetails(Field field) {
		StringBuffer buffer = new StringBuffer();
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			buffer.append(info.getName());
			buffer.append(": ");
			buffer.append(info.getCount());
			buffer.append(' ');
		}
		return buffer.toString();
	}


	public void reset() {
		countsValid = false;
		for (Class key : counters.keySet()) {
			Counter count = counters.get(key);
			count.reset();
		}
	}


	public void incrementCount(Class animalClass) {
		Counter count = counters.get(animalClass);
		if (count == null) {


			count = new Counter(animalClass.getName());
			counters.put(animalClass, count);
		}
		count.increment();
	}


	public void countFinished() {
		countsValid = true;
	}


	public boolean isViable(Field field) {

		int nonZero = 0;
		if (!countsValid) {
			generateCounts(field);
		}
		for (Class key : counters.keySet()) {
			Counter info = counters.get(key);
			if (info.getCount() > 0) {
				nonZero++;
			}
		}
		return nonZero > 1;
	}


	private void generateCounts(Field field) {
		reset();
		for (int row = 0; row < field.getDepth(); row++) {
			for (int col = 0; col < field.getWidth(); col++) {
				Object animal = field.getAnimalAt(row, col);
				if (animal != null) {
					incrementCount(animal.getClass());
				}
			}
		}
		countsValid = true;
	}


	public int getPopulationCount(Field field, Class key) {
		if (!countsValid) {
			generateCounts(field);
		}
		int total = 0;
		for (Class currentKey : counters.keySet()) {
			if (currentKey.equals(key)) {
				Counter counter = counters.get(currentKey);
				total = total + counter.getCount();
			}
		}
		return total;
	}
}

import java.util.List;
import java.util.Random;


public abstract class Animal extends Entity {


	private static final Random rand = Randomizer.getRandom();

	private boolean alive;

	private int age;

	private Gender gender = Gender.MALE;

	private boolean nocturnal;

	private int foodChainLevel;

	private int foodValue;

	private int foodLevel;

	private boolean sick;

	private int sickProbability;

	private int recoverProbability;

	private int sickStep;

	private int maxSickStep;


	public Animal(Field field, Location location) {
		super(field, location);
		alive = true;
		gender = Gender.randomGender();
		nocturnal = false;
		sick = false;
		sickProbability = 16;
	}


	abstract protected void normalAct(List<Animal> newAnimals);


	public void act(List<Animal> newAnimals, TimeCycle time) {
		incrementAge();
		incrementHunger();
		battleSickness();
		if (isAlive()) {
			if (time == TimeCycle.NIGHT && isNocturnal()) {

				normalAct(newAnimals);
			} else if (time == TimeCycle.DAY && isNocturnal()) {

				normalAct(newAnimals);
			} else if (time == TimeCycle.DAY && !isNocturnal()) {

				normalAct(newAnimals);
			}
		}
	}


	protected void incrementAge() {
		age++;
		if (age > getMaxAge()) {
			setDead();
		}
	}


	private boolean canBreed() {
		return age >= getBreedingAge();
	}


	private int breed() {
		int births = 0;
		if (canBreed() && rand.nextDouble() <= getBreedingProbability()) {
			births = rand.nextInt(getMaxLitterSize()) + 1;
		}
		return births;
	}


	protected void giveBirth(List<Animal> newAnimals) {


		if (this.getGender() == Gender.FEMALE) {
			Field field = getField();
			List<Location> free = field.getFreeAnimalAdjacentLocations(getLocation());
			int births = breed();
			for (int b = 0; b < births && free.size() > 0; b++) {
				Location loc = free.remove(0);
				Animal young = createNewAnimal(false, field, loc);
				newAnimals.add(young);
			}
		}
	}


	protected boolean isAlive() {
		return alive;
	}


	protected void setDead() {
		alive = false;
		if (getLocation() != null) {
			getField().clear(getLocation());
			setLocationNull();
			setFieldNull();
		}
	}


	protected void becomeSick() {
		if (!isSick()) {
			int randomNumber = rand.nextInt(getSickProbability());
			if (randomNumber == 1) {
				toggleSick();
			}
		}
	}


	protected void notSick() {
		if (isSick()) {
			int randomNumber = rand.nextInt(getRecoverProbability());
			if (randomNumber == 1) {
				toggleSick();
				sickStep = 0;
			}
		}
	}


	protected void battleSickness() {
		if (sick) {
			if (sickStep >= maxSickStep) {
				setDead();
				return;
			}
			sickStep++;
			Field field = getField();
			if (field != null) {
				spreadSickness(field);
				notSick();
			}
		} else {
			becomeSick();
		}
	}

	private void spreadSickness(Field field) {
		for (Location where : field.adjacentAnimalLocations(getLocation())) {
			Object animal = field.getAnimalAt(where);
			if (animal instanceof Animal) {
				Animal nearAnimal = (Animal) animal;
				if (nearAnimal.getClass().equals(getClass())) {
					nearAnimal.becomeSick();
				}
			}
		}
	}


	protected void incrementHunger() {
		foodLevel--;
		if (foodLevel <= 0) {
			setDead();
		}
	}


	protected void toggleNocturnal() {
		nocturnal = !nocturnal;

	}


	protected void toggleSick() {
		sick = !sick;

	}


	protected int getSickProbability() {
		return sickProbability;
	}


	protected void setSickProbability(int inputValue) {
		sickProbability = inputValue;
	}


	protected int getRecoverProbability() {
		return recoverProbability;
	}


	protected void setRecoverProbability(int inputValue) {
		recoverProbability = inputValue;
	}


	protected Gender getGender() {
		return gender;
	}


	protected int getFoodChainLevel() {
		return foodChainLevel;
	}

import java.util.List;
import java.util.Random;


public abstract class Prey extends Animal {

	private static final Random rand = Randomizer.getRandom();


	public Prey(boolean randomAge, Field field, Location location) {
		super(field, location);
		setAge(0);
		setFoodLevel(6);
		if (randomAge) {
			setAge(rand.nextInt(getMaxAge()));
		}
		setMaxSickStep(20);
	}


	protected void normalAct(List<Animal> newAnimals) {
		findFood();
		giveBirth(newAnimals);

		Location newLocation = getField().freeAnimalAdjacentLocation(getLocation());
		if (newLocation != null) {
			setLocation(newLocation);
		} else {

			setDead();
		}
	}


	private void findFood() {
		Field field = getField();
		Location where = getLocation();
		Object plant = field.getPlantAt(where);

		if (plant instanceof Plant) {
			Plant nearPlant = (Plant) plant;

			if (nearPlant.canEat()) {
				nearPlant.reduceStage();
				setFoodLevel(8);
			}
		}
	}

	@Override
	protected void placeAt(Location location) {
		getField().placeAnimal(this, location);
	}
}

