  6	
  7	public class Simulator {
  8	
  9	
 10		private static final int DEFAULT_WIDTH = 320;
 11	
 12		private static final int DEFAULT_DEPTH = 200;
 13	
 14		private static final double FLOWER_CREATION_PROBABILITY = 0.07;
 15	
 16		private static final double MOUSE_CREATION_PROBABILITY = 0.07;
 17	
 18		private static final double DUCK_CREATION_PROBABILITY = 0.07;
 19	
 20		private static final double BIRD_CREATION_PROBABILITY = 0.07;
 21	
 22		private static final double WOLF_CREATION_PROBABILITY = 0.03;
 23	
 24		private static final double BEAR_CREATION_PROBABILITY = 0.03;
 25	
 26		private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;
 27	
 28		private static final Weather DEFAULT_WEATHER = Weather.SUN;
 29	
 30		private static final int TIME_CYCLE_LENGTH = 4;
 31	
 32	
 33		private List<Animal> animals;
 34	
 35		private List<Plant> plants;
 36	
 37		private Field field;
 38	
 39		private int step;
 40	
 41		private SimulatorView gridView;
 42	
 43		private GraphView graphView;
 44	
 45		private TimeCycle currentTimeCycle;
 46	
 47		private Climate climate;
 48	
 49		private int sickPercentage;
 50	
 51	
 52		public Simulator() {
 53			this(DEFAULT_DEPTH, DEFAULT_WIDTH);
 54			currentTimeCycle = DEFAULT_TIMECYCLE;
 55		}
 56	
 57	
 58		public Simulator(int depth, int width) {
 59			if (width <= 0 || depth <= 0) {
 60				System.out.println("The dimensions must be greater than zero.");
 61				System.out.println("Using default values.");
 62				depth = DEFAULT_DEPTH;
 63				width = DEFAULT_WIDTH;
 64			}
 65	
 66	
 67			animals = new ArrayList<>();
 68	
 69			plants = new ArrayList<>();
 70			field = new Field(depth, width);
 71			climate = new Climate(DEFAULT_WEATHER);
 72	
 73	
 74			gridView = new SimulatorView(depth, width);
 75	
 76	
 77			graphView = new GraphView(1000, 500, 500);
 78	
 79	
 80			reset();
 81		}
 82	
 83	
 84		public void runLongSimulation() {
 85			simulate(4000);
 86		}
 87	
 88	
 89		public void simulate(int numSteps) {
 90			for (int i = 0; i < numSteps && gridView.isViable(field); i++) {
 91				simulateOneStep();
 92				delay(60);
 93			}
 94		}
 95	
 96	
 97		public void simulateOneStep() {
 98			step++;
 99			climate.updateClimate(step);
100			updatePlants();
101			List<Animal> newAnimals = new ArrayList<>();
102			updateAnimals(newAnimals);
103			animals.addAll(newAnimals);
104			updateTimeCycle();
105			sickPercentage = calculateSickPercentage();
106			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
107			graphView.showStatus(step, field);
108		}
109	
110	
111		public void reset() {
112			step = 0;
113			animals.clear();
114			plants.clear();
115			populate();
116			currentTimeCycle = TimeCycle.DAY;
117			climate.setCurrentWeather(Weather.SUN);
118	
119			sickPercentage = 0;
120			graphView.reset();
121			gridView.showStatus(step, currentTimeCycle, field, climate, sickPercentage);
122			graphView.showStatus(step, field);
123		}
124	
125	
126		private void populate() {
127			Random rand = Randomizer.getRandom();
128			field.clear();
129	
130			for (int row = 0; row < field.getDepth(); row++) {
131				for (int col = 0; col < field.getWidth(); col++) {
132					Location location = new Location(row, col);
133					populatePlant(rand, location);
134					populateAnimal(rand, location);
135				}
136			}
137		}
138	
139		private void populatePlant(Random rand, Location location) {
140			if (rand.nextDouble() <= FLOWER_CREATION_PROBABILITY) {
141				plants.add(new Flower(field, location));
142			} else {
143				plants.add(new Grass(field, location));
144			}
145		}
146	
147		private void populateAnimal(Random rand, Location location) {
148			if (rand.nextDouble() <= BIRD_CREATION_PROBABILITY) {
149				addAnimal(new Bird(true, field, location));
150			} else if (rand.nextDouble() <= MOUSE_CREATION_PROBABILITY) {
151				addAnimal(new Mouse(true, field, location));
152			} else if (rand.nextDouble() <= DUCK_CREATION_PROBABILITY) {
153				addAnimal(new Duck(true, field, location));
154			} else if (rand.nextDouble() <= WOLF_CREATION_PROBABILITY) {
155				addAnimal(new Wolf(true, field, location));
156			} else if (rand.nextDouble() <= BEAR_CREATION_PROBABILITY) {
157				addAnimal(new Bear(true, field, location));
158			}
159		}
160	
161		private void addAnimal(Animal animal) {
162			animals.add(animal);
163			graphView.setColor(animal.getClass(), animal.getObjectColor(climate));
164		}
165	
166		private void updatePlants() {
167			for (Plant plant : plants) {
168				plant.increaseStage(climate);
169			}
170		}
171	
172		private void updateAnimals(List<Animal> newAnimals) {
173			for (Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
174				Animal animal = it.next();
175				animal.act(newAnimals, currentTimeCycle);
176				if (!animal.isAlive()) {
177					it.remove();
178				}
179			}
180		}
181	
182		private void updateTimeCycle() {
183			if (step % TIME_CYCLE_LENGTH == 0) {
184				currentTimeCycle = currentTimeCycle.toggle();
185			}
186		}
187	
188		private int calculateSickPercentage() {
189			if (animals.isEmpty()) {
190				return 0;
191			}
192			int count = 0;
193			for (Animal animal : animals) {
194				if (animal.isSick()) {
195					count++;
196				}
197			}
198			return (count * 100) / animals.size();
199		}
200	
201	
202		private void delay(int millisec) {
203			try {
204				Thread.sleep(millisec);
205			} catch (InterruptedException ie) {
206				Thread.currentThread().interrupt();
207			}
208		}
209	}

