 83	
 84		public List<Location> getFreeAnimalAdjacentLocations(Location location) {
 85			List<Location> free = new ArrayList<>();
 86			List<Location> adjacent = adjacentAnimalLocations(location);
 87			for (Location next : adjacent) {
 88				if (getAnimalAt(next) == null) {
 89					free.add(next);
 90				}
 91			}
 92			return free;
 93		}
 94	
 95	
 96		public Location freeAnimalAdjacentLocation(Location location) {
 97	
 98			List<Location> free = getFreeAnimalAdjacentLocations(location);
 99			if (!free.isEmpty()) {
100				return free.get(0);
101			} else {
102				return null;
103			}
104		}
105	
106	
107		public List<Location> adjacentAnimalLocations(Location location) {
108			assert location != null : "Null location passed to adjacentLocations";
109	
110			List<Location> locations = new ArrayList<>();
111			if (location != null) {
112				int row = location.getRow();
113				int col = location.getCol();
114				for (int roffset = -1; roffset <= 1; roffset++) {
115					int nextRow = row + roffset;
116					if (nextRow >= 0 && nextRow < depth) {
117						for (int coffset = -1; coffset <= 1; coffset++) {
118							int nextCol = col + coffset;
119	
120							if (nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
121								locations.add(new Location(nextRow, nextCol));
122							}
123						}
124					}
125				}
126				Collections.shuffle(locations, rand);
127			}
128			return locations;
129		}
130	
131	
132		public int getDepth() {
133			return depth;
134		}
135	
136	
137		public int getWidth() {
138			return width;
139		}
140	}

 1	import java.util.LinkedHashMap;
 2	import java.util.Map;
 3	
 4	
 5	public class FieldStats {
 6	
 7		private final Map<Class<?>, Counter> counters;
 8	
 9		private boolean countsValid;
10	
11	
12		public FieldStats() {
13			counters = new LinkedHashMap<>();
14			countsValid = true;
15		}
16	
17	
18		public String getPopulationDetails(Field field) {
19			StringBuilder buffer = new StringBuilder();
20			if (!countsValid) {
21				generateCounts(field);
22			}
23			for (Counter info : counters.values()) {
24				buffer.append(info.getName());
25				buffer.append(": ");
26				buffer.append(info.getCount());
27				buffer.append(' ');
28			}
29			return buffer.toString();
30		}
31	
32	
33		public void reset() {
34			countsValid = false;
35			for (Counter count : counters.values()) {
36				count.reset();
37			}
38		}
39	
40	
41		public void incrementCount(Class<?> animalClass) {
42			Counter count = counters.get(animalClass);
43			if (count == null) {
44				count = new Counter(animalClass.getName());
45				counters.put(animalClass, count);
46			}
47			count.increment();
48		}
49	
50	
51		public void countFinished() {
52			countsValid = true;
53		}
54	
55	
56		public boolean isViable(Field field) {
57			if (!countsValid) {
58				generateCounts(field);
59			}
60			int nonZero = 0;
61			for (Counter info : counters.values()) {
62				if (info.getCount() > 0) {
63					nonZero++;
64				}
65			}
66			return nonZero > 1;
67		}
68	
69	
70		private void generateCounts(Field field) {
71			counters.clear();
72			for (int row = 0; row < field.getDepth(); row++) {
73				for (int col = 0; col < field.getWidth(); col++) {
74					Object animal = field.getAnimalAt(row, col);
75					if (animal != null) {
76						incrementCount(animal.getClass());
77					}
78				}
79			}
80			countsValid = true;
81		}
82	
83	
84		public int getPopulationCount(Field field, Class<?> key) {
85			if (!countsValid) {
86				generateCounts(field);
87			}
88			Counter counter = counters.get(key);
89			return counter == null ? 0 : counter.getCount();
90		}
91	}

