 79	
 80		class GraphPanel extends JComponent {
 81			private static final double SCALE_FACTOR = 0.8;
 82	
 83			private BufferedImage graphImage;
 84			private int[] lastVal;
 85			private int yMax;
 86	
 87	
 88			public GraphPanel(int width, int height, int startMax) {
 89				graphImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
 90				clearImage();
 91				lastVal = new int[colors.size()];
 92				Arrays.fill(lastVal, height);
 93				yMax = startMax;
 94			}
 95	
 96	
 97			public void newRun() {
 98				int height = graphImage.getHeight();
 99				int width = graphImage.getWidth();
100	
101				Graphics g = graphImage.getGraphics();
102				g.copyArea(4, 0, width - 4, height, -4, 0);
103				g.setColor(Color.BLACK);
104				g.drawLine(width - 4, 0, width - 4, height);
105				g.drawLine(width - 2, 0, width - 2, height);
106				lastVal = new int[colors.size()];
107				Arrays.fill(lastVal, height);
108				repaint();
109			}
110	
111	
112			public void update(int step, Field field, FieldStats stats) {
113				Graphics g = graphImage.getGraphics();
114	
115				int height = graphImage.getHeight();
116				int width = graphImage.getWidth();
117	
118				g.copyArea(1, 0, width - 1, height, -1, 0);
119	
120				stats.reset();
121	
122				int i = 0;
123				for (Map.Entry<Class<?>, Color> entry : colors.entrySet()) {
124					Class<?> nextClass = entry.getKey();
125					int count = stats.getPopulationCount(field, nextClass);
126	
127					int y = height - ((height * count) / yMax) - 1;
128					while (y < 0) {
129						scaleDown();
130						y = height - ((height * count) / yMax) - 1;
131					}
132					g.setColor(LIGHT_GRAY);
133					g.drawLine(width - 2, y, width - 2, height);
134					g.setColor(entry.getValue());
135					g.drawLine(width - 3, lastVal[i], width - 2, y);
136					lastVal[i] = y;
137					i++;
138				}
139	
140				repaint();
141	
142				stepLabel.setText(Integer.toString(step));
143				countLabel.setText(stats.getPopulationDetails(field));
144			}
145	
146	
147			public void scaleDown() {
148				Graphics g = graphImage.getGraphics();
149				int height = graphImage.getHeight();
150				int width = graphImage.getWidth();
151	
152				BufferedImage tmpImage = new BufferedImage(width, (int) (height * SCALE_FACTOR),
153						BufferedImage.TYPE_INT_RGB);
154				Graphics2D gtmp = (Graphics2D) tmpImage.getGraphics();
155	
156				gtmp.scale(1.0, SCALE_FACTOR);
157				gtmp.drawImage(graphImage, 0, 0, null);
158	
159				int oldTop = (int) (height * (1.0 - SCALE_FACTOR));
160	
161				g.setColor(Color.WHITE);
162				g.fillRect(0, 0, width, oldTop);
163				g.drawImage(tmpImage, 0, oldTop, null);
164	
165				yMax = (int) (yMax / SCALE_FACTOR);
166	
167				for (int i = 0; i < lastVal.length; i++) {
168					lastVal[i] = oldTop + (int) (lastVal[i] * SCALE_FACTOR);
169				}
170	
171				repaint();
172			}
173	
174	
175			public void clearImage() {
176				Graphics g = graphImage.getGraphics();
177				g.setColor(Color.WHITE);
178				g.fillRect(0, 0, graphImage.getWidth(), graphImage.getHeight());
179				repaint();
180			}
181	
182	
183			@Override
184			public Dimension getPreferredSize() {
185				return new Dimension(graphImage.getWidth(), graphImage.getHeight());
186			}
187	
188	
189			@Override
190			public boolean isOpaque() {
191				return true;
192			}
193	
194	
195			@Override
196			public void paintComponent(Graphics g) {
197				if (graphImage != null) {
198					g.drawImage(graphImage, 0, 0, null);
199				}
200			}
201		}
202	}
